import { blankComments } from "../../utils/blankComments/index.js";
import { findCommentSpans, findEscapeSpans } from "../../utils/findCommentSpans/index.js";
import { hideFalseInlineComments } from "../../utils/hideFalseInlineComments/index.js";
import { maskEscapes } from "../../utils/maskEscapes/index.js";
import { maskStrings } from "../../utils/maskStrings/index.js";
import { maskAddressTokens } from "../maskAddressTokens/index.js";
import { inlineCommentReading } from "../readsInlineComments/index.js";
/**
 * Builds the copy of a node's text a scan is handed in place of the text, and returns the comments it was built from.
 *
 * `style-search` reads comments, strings and escapes by rules of its own: a `//` comment ends on a line feed only, a `//` opens one anywhere, the `*\/` closing one block comment against the `/*` opening the next spell a third, and a backslash covers nothing, so the `,` of `a\,b` is a comma to it; its reading of a string is {@link maskStrings}'s question. The copy blanks every comment, masks every string, every escape ({@link maskEscapes}), the content of every address token the scan would misread ({@link maskAddressTokens}) and every false `//`, at the same length, so every position holds. The syntax says which `//` is a comment, since the pair in `myurl(//a)` is code in plain CSS.
 *
 * The second copy masks the escapes alone, for the whitespace beside a delimiter: over the text an escaped space passes for a run in front of the comma of `a\ ,b`, which `never` then takes away, leaving `a\,b`; the comments stay, since a blanked one would pass for a run too, and so does the whitespace closing a hexadecimal escape, which a rule may write or take away in front of a delimiter ({@link maskEscapes}).
 * @param text - The value or parameters the search runs over.
 * @param node - The node the text was read from.
 * @param result - The Stylelint result.
 * @returns The copy, the copy the runs are read over, and the comment spans of the text.
 */
export function searchCopy(text, node, result) {
    let reading = inlineCommentReading(node, result);
    let commentSpans = findCommentSpans(text, reading);
    let escapes = findEscapeSpans(text, reading);
    // No spans for the masking: every comment is gone from the copy, so every `//` left in it opens none
    return {
        searchString: hideFalseInlineComments(maskAddressTokens(maskStrings(maskEscapes(blankComments(text, commentSpans), escapes), []), text, node, result), []),
        runString: maskEscapes(text, escapes, true),
        commentSpans,
    };
}
